<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';
require_once __DIR__.'/security.php';
require_once __DIR__.'/resident_portal_lib.php';
header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('Cache-Control: no-store');
$pdo=residentPortalDb();$savedPath=tenantPrivateFile('lookups.php');$lookups=is_file($savedPath)?require $savedPath:[];$portalLists=(array)($lookups['resident_portal']??[]);
$portalDefaults=['TypeMelding'=>['Storing','Schade','Overlast','Vraag','Klacht','Anders'],'OnderwerpMelding'=>['Lift','Verwarming','Water/lekkage','Elektriciteit','Schoonmaak','Geluid','Toegang/deuren','Gemeenschappelijke ruimte','Anders'],'LocatieMelding'=>['Appartement/woning','Hal/entree','Lift','Trappenhuis','Parkeergarage','Berging','Buitenruimte','Anders'],'UrgentieMelding'=>['Normaal','Binnen enkele dagen','Spoed']];
foreach($portalDefaults as $field=>$defaults)if(!isset($portalLists[$field])||!is_array($portalLists[$field])||!$portalLists[$field])$portalLists[$field]=$defaults;
$fallback=['TypeMelding'=>['Probleem of storing','Vraag','Klacht','Suggestie'],'OnderwerpMelding'=>['Lift','Water of lekkage','Verwarming of ventilatie','Schoonmaak of algemene ruimte','Geluid of overlast','Deur, slot of sleutel','Afval','Anders'],'LocatieMelding'=>['In mijn appartement','Hal A','Hal B','Hal C','Hal D','Andere algemene ruimte','Buiten bij het gebouw','Anders of ik weet het niet'],'UrgentieMelding'=>['Spoed — direct gevaar of snel erger','Dringend — vandaag bekijken','Normaal — binnen enkele dagen','Geen haast']];
foreach($fallback as $key=>$values){$portalLists[$key]=array_values(array_filter(array_map('strval',(array)($portalLists[$key]??$values)),static fn($v)=>trim($v)!==''));if(!$portalLists[$key])$portalLists[$key]=$values;}
$errors=[];$sent=false;$values=['type'=>'','subject'=>'','location'=>'','urgency'=>'','description'=>'','name'=>'','unit'=>'','phone'=>'','email'=>''];
function residentFormEsc(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function residentReportRateLimit():void{$key=hash('sha256',(string)($_SERVER['REMOTE_ADDR']??'unknown'));$path=uploadDirectory('resident-rate-limits').'/resident-report-'.$key.'.json';$now=time();$fp=fopen($path,'c+');if(!$fp)throw new RuntimeException('Verzenden is op dit moment niet mogelijk.');try{flock($fp,LOCK_EX);$data=json_decode(stream_get_contents($fp)?:'{}',true);$times=array_values(array_filter((array)($data['times']??[]),static fn($t)=>(int)$t>$now-3600));if(count($times)>=4)throw new SafeInputException('Er zijn vandaag al meerdere meldingen vanaf deze verbinding verstuurd. Neem contact op met het bestuur als u nog hulp nodig heeft.');$times[]=$now;ftruncate($fp,0);rewind($fp);fwrite($fp,json_encode(['times'=>$times]));fflush($fp);@chmod($path,0600);}finally{flock($fp,LOCK_UN);fclose($fp);}}
function residentValidateChoice(string $value,array $options,string $label):string{$value=trim($value);if($value===''||!in_array($value,$options,true))throw new SafeInputException('Kies een geldige optie bij '.$label.'.');return $value;}

if($_SERVER['REQUEST_METHOD']==='POST'){
    foreach($values as $key=>$unused)$values[$key]=mb_substr(trim((string)($_POST[$key]??'')),0,$key==='description'?5000:($key==='name'?160:($key==='email'?254:($key==='phone'?50:($key==='unit'?40:500)))));
    try{
        verifyCsrf();if(trim((string)($_POST['website']??''))!=='')throw new SafeInputException('De melding kon niet worden verwerkt.');
        $values['type']=residentValidateChoice($values['type'],$portalLists['TypeMelding'],'soort melding');$values['subject']=residentValidateChoice($values['subject'],$portalLists['OnderwerpMelding'],'onderwerp');$values['location']=residentValidateChoice($values['location'],$portalLists['LocatieMelding'],'locatie');$values['urgency']=residentValidateChoice($values['urgency'],$portalLists['UrgentieMelding'],'urgentie');
        if($values['description']===''||$values['name']===''||$values['unit']==='')throw new SafeInputException('Vul de omschrijving, uw naam en huisnummer in.');
        if(mb_strlen($values['description'])<10)throw new SafeInputException('Beschrijf uw melding iets uitgebreider, zodat het bestuur u kan helpen.');
        if($values['phone']===''&&$values['email']==='')throw new SafeInputException('Vul ten minste een telefoonnummer of e-mailadres in.');
        if($values['email']!==''&&!filter_var($values['email'],FILTER_VALIDATE_EMAIL))throw new SafeInputException('Controleer het e-mailadres.');
        if($values['phone']!==''&&!preg_match('/^[+0-9() .-]{7,30}$/',$values['phone']))throw new SafeInputException('Controleer het telefoonnummer.');
        residentReportRateLimit();
        $reference='M-'.strtoupper(bin2hex(random_bytes(4)));$title='Bewonersmelding '.$reference.' · '.$values['type'].' · '.$values['urgency'];
        $plain="Nieuwe melding via het bewonersportaal\nReferentie: $reference\n\nSoort: {$values['type']}\nOnderwerp: {$values['subject']}\nLocatie: {$values['location']}\nUrgentie volgens bewoner: {$values['urgency']}\n\nOmschrijving:\n{$values['description']}\n\nNaam: {$values['name']}\nHuisnummer/appartement: {$values['unit']}\nTelefoon: ".($values['phone']?:'niet opgegeven')."\nE-mail: ".($values['email']?:'niet opgegeven')."\n\nIngezonden via het openbare bewonersportaal.";
        $e=static fn(string $v)=>htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
        $html='<h2>Nieuwe melding via het bewonersportaal</h2><p><strong>Referentie:</strong> '.$e($reference).'</p><table cellpadding="6" cellspacing="0" border="0"><tr><th align="left">Soort</th><td>'.$e($values['type']).'</td></tr><tr><th align="left">Onderwerp</th><td>'.$e($values['subject']).'</td></tr><tr><th align="left">Locatie</th><td>'.$e($values['location']).'</td></tr><tr><th align="left">Urgentie volgens bewoner</th><td>'.$e($values['urgency']).'</td></tr><tr><th align="left">Naam</th><td>'.$e($values['name']).'</td></tr><tr><th align="left">Huisnummer/appartement</th><td>'.$e($values['unit']).'</td></tr><tr><th align="left">Telefoon</th><td>'.$e($values['phone']?:'Niet opgegeven').'</td></tr><tr><th align="left">E-mail</th><td>'.$e($values['email']?:'Niet opgegeven').'</td></tr></table><h3>Omschrijving</h3><p>'.nl2br($e($values['description'])).'</p><p>Ingezonden via het openbare bewonersportaal.</p>';
        residentPortalSendMail($pdo,$title,$plain,$html,$values['email']);$sent=true;$values=array_fill_keys(array_keys($values),'');
    }catch(SafeInputException $e){$errors[]=$e->getMessage();}catch(Throwable $e){securityIncident($e);$errors[]='Uw melding kon niet worden verstuurd. Probeer het later opnieuw of neem contact op met het bestuur.';}
}
